{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks server-side encryption",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled. Without encryption, sensitive data stored in the bucket could be exposed if unauthorized access occurs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}",
  "fix_summary": "Added server-side encryption configuration to the S3 bucket to ensure data at rest is encrypted using AES256."
}
